const VIDEOS_KEY = "ytc_videos";
const CHANNELS_KEY = "ytc_channels";

async function fetchHtml(url) {
  const res = await fetch(url, { headers: { "Accept-Language": "en-US,en;q=0.9" } });
  if (!res.ok) throw new Error(`HTTP ${res.status} fetching ${url}`);
  return await res.text();
}

function extractInitialData(html) {
  const match = html.match(/var ytInitialData = (\{.*?\});<\/script>/);
  if (!match) throw new Error("Could not find ytInitialData");
  return JSON.parse(match[1]);
}

async function resolveChannel(input) {
  let url = input;
  if (!url.startsWith("http")) {
    if (url.startsWith("@") || url.startsWith("UC")) {
      url = `https://www.youtube.com/${url}`;
    } else {
      url = `https://www.youtube.com/@${url}`;
    }
  }
  
  const html = await fetchHtml(url);
  const data = extractInitialData(html);
  
  const header = data.header?.c4TabbedHeaderRenderer || data.header?.pageHeaderRenderer;
  if (!header) throw new Error("Could not parse channel header");
  
  let channelId, title, thumbnail;
  
  if (data.header?.c4TabbedHeaderRenderer) {
    channelId = header.channelId;
    title = header.title;
    thumbnail = header.avatar?.thumbnails?.[0]?.url;
  } else {
    channelId = data.metadata?.channelMetadataRenderer?.externalId;
    title = header.pageTitle;
    thumbnail = header.content?.pageHeaderViewModel?.image?.decoratedAvatarViewModel?.avatar?.avatarViewModel?.image?.sources?.[0]?.url;
  }

  if (!channelId || !title) throw new Error("Could not extract channel details");
  
  // Store channel info locally
  const stored = await chrome.storage.local.get(CHANNELS_KEY);
  const channels = stored[CHANNELS_KEY] || {};
  channels[channelId] = { id: channelId, title, thumbnail };
  await chrome.storage.local.set({ [CHANNELS_KEY]: channels });
  
  return channels[channelId];
}

async function scrapeVideos(channelId, isShorts) {
  const tab = isShorts ? "shorts" : "videos";
  console.log(`Scraping ${tab} for channel ${channelId}`);
  
  try {
    const html = await fetchHtml(`https://www.youtube.com/channel/${channelId}/${tab}`);
    console.log(`Fetched HTML, length: ${html.length}`);
    
    const data = extractInitialData(html);
    console.log(`Extracted initial data`);
    
    const tabs = data.contents?.twoColumnBrowseResultsRenderer?.tabs || [];
    console.log(`Found ${tabs.length} tabs`);
    
    const currentTab = tabs.find(t => t.tabRenderer?.selected)?.tabRenderer;
    if (!currentTab) {
      console.log('No selected tab found');
      return [];
    }
    
    const items = currentTab.content?.richGridRenderer?.contents || [];
    console.log(`Found ${items.length} items in grid`);
    
    const videos = [];
    
    for (const item of items) {
      let videoId, title, thumbnail, url, publishedAt;
      
      if (isShorts) {
        // Handle new shorts structure with shortsLockupViewModel
        const shortsData = item.richItemRenderer?.content?.shortsLockupViewModel;
        if (!shortsData) continue;
        
        // Extract video ID from entityId (format: "shorts-shelf-item-{videoId}")
        const entityId = shortsData.entityId || "";
        videoId = entityId.replace("shorts-shelf-item-", "");
        
        // Extract title from accessibilityText - YouTube formats it as "Title – X views – play Short"
        const accessibilityText = shortsData.accessibilityText || "";
        title = accessibilityText.split(" – ")[0]; // Remove the " – X views – play Short" part
        
        // If title is empty, try to extract from other fields
        if (!title) {
          title = shortsData.viewModel?.title?.content || shortsData.headline?.simpleText || "Short";
        }
        
        // Extract thumbnail from thumbnailViewModel - check multiple possible paths
        thumbnail = shortsData.thumbnailViewModel?.image?.sources?.[0]?.url || 
                   shortsData.contentImage?.thumbnailViewModel?.image?.sources?.[0]?.url ||
                   shortsData.avatarViewModel?.image?.sources?.[0]?.url ||
                   shortsData.metadata?.thumbnailViewModel?.image?.sources?.[0]?.url;
        
        // Extract URL from onTap command
        url = shortsData.onTap?.innertubeCommand?.commandMetadata?.webCommandMetadata?.url;
        if (url && !url.startsWith("http")) {
          url = `https://www.youtube.com${url}`;
        }
        
        // Set default publish time for shorts
        publishedAt = new Date().toISOString();
        
      } else {
        // Handle new video structure with lockupViewModel
        const lockupData = item.richItemRenderer?.content?.lockupViewModel;
        if (!lockupData) {
          if (videos.length < 3) console.log('No lockupData found in item');
          continue;
        }
        
        // Log structure for debugging first few items
        if (videos.length < 3) {
          console.log('Lockup structure:', JSON.stringify(lockupData, null, 2).substring(0, 800));
        }
        
        // Extract thumbnail first (it contains the video ID in the URL)
        thumbnail = lockupData.contentImage?.thumbnailViewModel?.image?.sources?.[0]?.url;
        
        // Extract video ID from thumbnail URL (format: https://i.ytimg.com/vi/{videoId}/hq720.jpg)
        if (thumbnail) {
          const thumbnailMatch = thumbnail.match(/\/vi\/([^\/]+)/);
          videoId = thumbnailMatch ? thumbnailMatch[1] : null;
        }
        
        // Extract title from accessibilityText or viewModel
        title = lockupData.accessibilityText || lockupData.viewModel?.title?.content || lockupData.headline?.simpleText || "";
        
        // Try to extract publish date from metadata if available
        publishedAt = new Date().toISOString(); // fallback to current time
        if (lockupData.metadata?.publishedTimeText?.content) {
          // Try to parse relative time like "2 days ago"
          const timeText = lockupData.metadata.publishedTimeText.content;
          // This is a rough approximation - YouTube doesn't always provide exact timestamps
          if (timeText.includes('day')) {
            const days = parseInt(timeText) || 1;
            const date = new Date();
            date.setDate(date.getDate() - days);
            publishedAt = date.toISOString();
          } else if (timeText.includes('week')) {
            const weeks = parseInt(timeText) || 1;
            const date = new Date();
            date.setDate(date.getDate() - (weeks * 7));
            publishedAt = date.toISOString();
          } else if (timeText.includes('month')) {
            const months = parseInt(timeText) || 1;
            const date = new Date();
            date.setMonth(date.getMonth() - months);
            publishedAt = date.toISOString();
          } else if (timeText.includes('hour')) {
            const hours = parseInt(timeText) || 1;
            const date = new Date();
            date.setHours(date.getHours() - hours);
            publishedAt = date.toISOString();
          }
        }
        
        // Construct URL
        url = videoId ? `https://www.youtube.com/watch?v=${videoId}` : null;
        
        if (videos.length < 3) {
          console.log(`Extracted video - ID: ${videoId}, URL: ${url}, Title: ${title}, Thumbnail: ${thumbnail}`);
        }
      }
      
      if (!videoId || !url) continue;
      
      videos.push({
        id: videoId,
        channel_id: channelId,
        title: title || "Unknown title",
        thumbnail: thumbnail || "",
        published_at: (publishedAt || new Date()).toISOString(),
        is_short: isShorts,
        url: url
      });
    }
    
    console.log(`Successfully scraped ${videos.length} ${tab}`);
    return videos;
  } catch (err) {
    console.error(`Error scraping ${tab} for channel ${channelId}:`, err);
    return [];
  }
}

async function refreshChannels(channelIds) {
  const stored = await chrome.storage.local.get(VIDEOS_KEY);
  let allVideos = stored[VIDEOS_KEY] || [];
  
  // Remove old videos for these channels to replace them
  allVideos = allVideos.filter(v => !channelIds.includes(v.channel_id));
  
  for (const id of channelIds) {
    try {
      const videos = await scrapeVideos(id, false);
      const shorts = await scrapeVideos(id, true);
      allVideos.push(...videos, ...shorts);
    } catch (err) {
      console.error(`Failed to refresh channel ${id}:`, err);
    }
  }
  
  // Keep only the latest 1000 videos to avoid hitting storage limits
  if (allVideos.length > 1000) {
    allVideos = allVideos.slice(-1000);
  }
  
  await chrome.storage.local.set({ [VIDEOS_KEY]: allVideos });
  return { refreshed: channelIds.length };
}

chrome.action.onClicked.addListener(() => {
  chrome.tabs.create({ url: chrome.runtime.getURL("dashboard.html") });
});

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  (async () => {
    try {
      switch (msg.type) {
        case "RESOLVE_CHANNEL": {
          const channel = await resolveChannel(msg.input);
          sendResponse({ ok: true, channel });
          break;
        }
        case "REFRESH_CHANNELS": {
          const result = await refreshChannels(msg.channelIds || []);
          sendResponse({ ok: true, result });
          break;
        }
        default:
          sendResponse({ ok: false, error: "Unknown message type" });
      }
    } catch (err) {
      sendResponse({ ok: false, error: err.message });
    }
  })();
  return true;
});
